const crypto=require('crypto');
const secret=String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET||'').trim();
const url=String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL||'').trim();
if(secret.length<32) throw new Error('enrichment_secret_not_configured');
if(!/\/api\/v1\/automation\/control\/receipt$/.test(url)) throw new Error('enrichment_control_url_invalid');
const id=String($execution.id||'').trim().slice(0,120);
if(!id) throw new Error('enrichment_execution_id_missing');
const body=JSON.stringify({schema_version:1,action:'PREPARE_R2_ENRICHMENT_WORKLIST',source:'mtgjson',execution_id:id,occurred_at:new Date().toISOString()});
const timestamp=String(Math.floor(Date.now()/1000));
const signature='sha256='+crypto.createHmac('sha256',secret).update(timestamp+'.'+body,'utf8').digest('hex');
return [{json:{url:url.replace(/\/control\/receipt$/,'/commands/catalogue/prepare-enrichment-worklist'),body,timestamp,signature}}];

const response=$input.first().json||{};
const status=Number(response.statusCode);
if(!Number.isInteger(status)||status<200||status>=300)throw new Error('enrichment_http_'+String(status));
const r=response.body||{};
if(r.accepted!==true||r.source!=='mtgjson'||!r.execution_id||r.metadata_only!==true)throw new Error('enrichment_receipt_invalid');
if(r.scope!=='EXACT_IDENTITY_REVIEW_AND_SOLD_EVIDENCE_TASKS_ONLY'||r.artwork_published!==false||r.market_values_written!==0||r.shopify_updated!==false||r.ownership_or_price_changed!==false)throw new Error('enrichment_scope_overreach');
if(!['PRIVATE_ENRICHMENT_WORKLIST_VERIFIED','NO_ACTIVE_CATALOGUE_GENERATION','STALE_GENERATION_PRIVATE_ONLY'].includes(r.status))throw new Error('enrichment_status_invalid');
if(r.status==='PRIVATE_ENRICHMENT_WORKLIST_VERIFIED'){
  if(!/^[a-f0-9]{64}$/.test(String(r.source_manifest_sha256))||!Number.isInteger(r.generation)||r.generation<1||!Number.isInteger(r.processed_parts)||r.processed_parts<1||r.processed_parts>6||!Array.isArray(r.worklist_sha256)||r.worklist_sha256.length!==r.processed_parts||r.worklist_sha256.some(d=>!/^[a-f0-9]{64}$/.test(d))||!Number.isInteger(r.candidate_count)||r.candidate_count<1)throw new Error('enrichment_r2_proof_invalid');
}
if(r.status==='STALE_GENERATION_PRIVATE_ONLY')throw new Error('enrichment_source_changed_during_batch');
if(r.status==='NO_ACTIVE_CATALOGUE_GENERATION')throw new Error('enrichment_source_catalogue_unavailable');
return [{json:{source:r.source,status:r.status,source_manifest_sha256:r.source_manifest_sha256,worklist_sha256:r.worklist_sha256,candidate_count:r.candidate_count,identity_review_count:r.identity_review_count,artwork_published:false,market_values_written:0}}];
